/**
 * RRF Integration: Multi-Signal Ranking with Reciprocal Rank Fusion
 *
 * Combines BM25 (lexical), concept overlap, ANN (semantic), and Neo4j (graph)
 * signals via RRF to produce a unified ranked list of context hits.
 *
 * Formula: RRF(d) = Σ weight_i / (k + rank_i(d))
 * Default k=60 keeps early positions dominant while avoiding rank=1 singularity.
 */

import type { Pool } from 'pg';
import type { Redis } from 'ioredis';
import { RETRIEVAL_LIMITS } from './search-contract.js';
import { combineViaRRF, type ContextHit, type RRFResult, type RetrievalLaneName } from './rrf-combiner.js';
import type { DispatcherOrchestrationResult } from '../dispatcher/dispatcher-orchestrator.js';
import { RRF_DEFAULT_WEIGHTS } from './rrf-contract.js';
import { fetchAuthorityScores } from '../search/neo4j-rerank.js';
import {
  resolveEmbeddingLane,
  EmbeddingLaneTelemetryReason,
  emitEmbeddingLaneTelementry,
} from './resolve-embedding-lane.js';
import { resolveCanonicalIdentity, type IdentityResolutionSource } from './identity-resolution.js';

export type { IdentityResolutionSource };

export interface ResolvedCandidateId {
  id: string;
  source: IdentityResolutionSource;
}

/**
 * Resolve a lane hit's canonical dedup identity. Thin adapter over the shared
 * `identity-resolution.ts::resolveCanonicalIdentity` primitive — same precedence
 * (symbol_version_id -> packet_key -> content_hash -> source_ref -> lane-local fallback), just mapped from
 * `ContextHit`'s nested `metadata` shape into the primitive's flat input shape.
 *
 * Without this, combineViaRRF's `deduplicateBy: 'id'` collapses candidates on
 * whatever each lane happened to set as `id` — for the Qdrant lane that's
 * `qdrant_id ?? stable_key ?? file_path`, for BM25/TurboVec it's a lane-local
 * stable key. None of those are the canonical symbol identity, so a symbol
 * with multiple projections (multiple Qdrant points, a BM25 row, a TurboVec
 * candidate) can currently cast more than one independent RRF vote.
 */
export function resolveCanonicalCandidateId(hit: ContextHit): ResolvedCandidateId {
  const metadata = (hit.metadata ?? {}) as Record<string, unknown>;
  const resolved = resolveCanonicalIdentity({
    symbolVersionId: (metadata.symbol_version_id ?? metadata.symbolVersionId) as string | undefined,
    packetKey: (metadata.packet_key ?? metadata.packetKey) as string | undefined,
    contentHash: (metadata.content_hash ?? metadata.contentHash) as string | undefined,
    sourceRef: (metadata.source_ref ?? metadata.sourceRef) as string | undefined,
    fallbackId: hit.id,
  });
  // `resolved.status === 'degraded'` corresponds exactly to `source === 'lane_id_fallback'` —
  // callers here still key off `source` (pre-existing public shape); see
  // CANONICAL_QDRANT_IDENTITY_PAYLOAD for why the fallback tier must stay observable, not silent.
  return { id: resolved.canonicalId, source: resolved.source };
}

/**
 * Rewrite every hit's `id` to its canonical dedup identity before fusion, and record
 * `identity_resolution_source` on every hit so downstream smoke/observability can measure how
 * often fusion is running on real canonical identity versus the degraded lane-id fallback.
 * Lanes that carry no identity metadata (e.g. concept_overlap) still get tagged
 * `lane_id_fallback` even though their `id` is left unchanged — this only tightens dedup where
 * canonical fields are available, it never weakens it, but it never hides the fallback either.
 * The lane-local id is preserved as `raw_lane_id` so per-lane provenance (e.g. which Qdrant
 * point matched) survives even after the RRF-facing id has been normalized.
 */
export function normalizeCanonicalIdentity(hits: ContextHit[]): ContextHit[] {
  return hits.map((hit) => {
    const resolved = resolveCanonicalCandidateId(hit);
    return {
      ...hit,
      id: resolved.id,
      metadata: {
        ...(hit.metadata ?? {}),
        identity_resolution_source: resolved.source,
        ...(resolved.id !== hit.id ? { raw_lane_id: hit.id } : {}),
      },
    };
  });
}

/**
 * TODO: no prior implementation of this function was found anywhere in the
 * repo (grepped repo-wide) — this is a minimal pass-through, not a restored
 * original. It exists so the file type-checks; verify the intended
 * normalization behavior (field stripping? id collision handling?) before
 * relying on its output for ranking-affecting logic.
 */
function normalizeQdrantMetadata(
  record: Record<string, unknown>,
  id: string
): Record<string, unknown> {
  return { ...record, id };
}

function truncateEmbeddingForCollection(
  embedding: number[],
  collection: string
): number[] {
  if (collection === 'codebase_chunks_384_hybrid') {
    if (embedding.length !== 384) {
      throw new Error(
        `384-hybrid collection requires a 384-dim query vector; got ${embedding.length}`
      );
    }
    const norm = Math.sqrt(embedding.reduce((sum, value) => sum + value * value, 0));
    return norm > 0 ? embedding.map((value) => value / norm) : embedding;
  }

  if (collection === 'codebase_chunks_768' && embedding.length !== 768) {
    throw new Error(`768 collection requires a 768-dim query vector; got ${embedding.length}`);
  }

  return embedding;
}

async function loadRrfExecutionDeps() {
  const [
    bm25Module,
    conceptModule,
    gemmaModule,
    neoGraphModule,
    neoRerankModule,
    turboModule,
    qdrantModule,
    vectorConfigModule,
    subgraphModule,
    signalModule,
    dispatcherTopoModule,
    dispatcherSignalModule,
  ] = await Promise.all([
    import('./bm25-search.js'),
    import('./concept-overlap-search.js'),
    import('./concept-extraction-tool.js'),
    import('./neo4j-graph-signal.js'),
    import('$lib/server/search/neo4j-rerank.js'),
    import('./turbovec-prefilter.js'),
    import('$lib/server/search/qdrant-search.js'),
    import('$lib/server/config/vector-config.js'),
    import('./subgraph-seed-neighborhood.js'),
    import('./signal-normalizer.js'),
    import('../dispatcher/dispatcher-topology-service.js'),
    import('../dispatcher/dispatcher-signal-extractor.js'),
  ]);

  return {
    bm25SearchIndexed: bm25Module.bm25SearchIndexed,
    conceptOverlapSearch: conceptModule.conceptOverlapSearch,
    extractQueryConceptsViaGemma: gemmaModule.extractQueryConceptsViaGemma,
    queryNeoJsGraphSignal: neoGraphModule.queryNeoJsGraphSignal,
    queryNeoJsGraphSignalByNames: neoGraphModule.queryNeoJsGraphSignalByNames,
    expandNeighbours: neoRerankModule.expandNeighbours,
    fetchAuthorityScores: neoRerankModule.fetchAuthorityScores,
    turbovecSearch: turboModule.turbovecSearch,
    searchCodebaseAnn: qdrantModule.searchCodebaseAnn,
    buildVectorPayload: vectorConfigModule.buildVectorPayload,
    toStableFileKey: subgraphModule.toStableFileKey,
    computeTopologClusterMatchSignal: signalModule.computeTopologClusterMatchSignal,
    computeCommunityAuthoritySignal: signalModule.computeCommunityAuthoritySignal,
    computeTopologyBlendSignal: signalModule.computeTopologyBlendSignal,
    extractCanonicalPacketFromMetadata: signalModule.extractCanonicalPacketFromMetadata,
    buildCommunityAuthorityMap: signalModule.buildCommunityAuthorityMap,
    mergeTopologyWeights: signalModule.mergeTopologyWeights,
    TOPOLOGY_RRF_WEIGHTS: signalModule.TOPOLOGY_RRF_WEIGHTS,
    generateDispatcherTopologyHits: dispatcherTopoModule.generateDispatcherTopologyHits,
    getDispatcherSignalLaneWeight: dispatcherTopoModule.getDispatcherSignalLaneWeight,
    DISPATCHER_RRF_WEIGHTS: dispatcherSignalModule.DISPATCHER_RRF_WEIGHTS,
  };
}

export interface RRFIntegrationOptions {
  k?: number; // RRF constant (default 60)
  weights?: Partial<Record<string, number>>;
  topK?: number; // results to return (default 20)
  minScore?: number; // filter results below this RRF score (default 0.001)
  deduplicateBy?: 'id' | 'text'; // default 'id'
  dispatcherResult?: DispatcherOrchestrationResult; // Optional dispatcher result for topology signal integration (Session 117)
}

export interface RRFIntegrationOutput {
  results: RRFResult[];
  breakdown: {
    bm25Count: number;
    conceptCount: number;
    qdrantCount: number;
    turbovecCount: number;
    neoCount: number;
    topologyClusterCount: number;
    communityAuthorityCount: number;
    dispatcherSignalCount?: number; // Session 117: Dispatcher signal hits
  };
  durationMs: number;
  timings?: {
    bm25_ms: number;
    qdrant_ms: number;
    turbovec_ms: number;
    neo4j_ms: number;
    redis_ms: number;
    gemma4_ms: number;
    rrf_ms: number;
    pgvector_ms?: number;
    concept_overlap_ms?: number;
    topology_ms?: number;
    dispatcher_signal_ms?: number; // Session 117: Dispatcher signal extraction time
  };
}

/**
 * Query Qdrant for vector similarity results on atlas_packets collection.
 */
async function queryQdrantVectorSignal(
  query: string,
  embedding: number[] | null,
  topK: number,
  seedRefs: string[] = []
): Promise<Array<{ id: string; score: number; text?: string; metadata?: Record<string, unknown> }>> {
  if (!embedding) return [];

  const normalizeQdrantMetadata = (payload: Record<string, unknown>, fallbackId: string) => ({
    packet_key: String(payload.packet_key ?? payload.packetKey ?? fallbackId ?? '').trim() || null,
    source_ref: String(
      payload.source_ref ?? payload.sourceRef ?? payload.canonicalSourceRef ?? payload.file_path ?? payload.filePath ?? ''
    ).trim() || null,
    content_hash: String(payload.content_hash ?? payload.contentHash ?? payload.sha256 ?? payload.source_hash ?? payload.sourceHash ?? '').trim() || null,
    tree_node_id: String(payload.tree_node_id ?? payload.treeNodeId ?? payload.tree_node ?? '').trim() || null,
    feature_id: payload.feature_id ?? payload.featureId ?? null,
    feature_label: payload.feature_label ?? payload.featureLabel ?? null,
    workspace_revision: String(payload.workspace_revision ?? payload.workspaceRevision ?? payload.revision ?? '').trim() || null,
    file_path: String(payload.file_path ?? payload.filePath ?? null) || null,
    qdrant_point_id: fallbackId,
    qdrant_collection: payload.qdrant_collection ?? payload.qdrantCollection ?? null,
    som_cluster: payload.som_cluster ?? payload.somCluster ?? null,
    som_bmu_row: payload.som_bmu_row ?? null,
    som_bmu_col: payload.som_bmu_col ?? null,
    centroid_id: payload.centroid_id ?? null,
    cluster_id: payload.cluster_id ?? payload.clusterId ?? null,
    community_id: payload.community_id ?? payload.communityId ?? null,
  });

  try {
    const { buildVectorPayload } = await import('$lib/server/config/vector-config.js');
    const { searchCodebaseAnn } = await import('$lib/server/search/qdrant-search.js');
    const denseLimit = Math.max(topK * 2, topK);
    // Canonical semantic_768 lane only. `codebase_chunks_384_hybrid` was previously included
    // here but (a) is empty in production (0 points, verified live), (b) requires a 384-dim
    // query vector while `embedding` here is always the canonical 768-dim EmbeddingGemma
    // output, so `truncateEmbeddingForCollection` threw synchronously inside `collections.map()`
    // below whenever this path was reached — the exception propagated out of the try block and
    // the catch handler returned `[]` for the WHOLE function, silently zeroing out the
    // canonical 768 dense-vector lane too, not just the legacy collection. (c) legacy 384
    // collections must never enter production RRF per the semantic_768 canonical contract.
    const collections = ['codebase_chunks_768'];

    if (seedRefs.length > 0) {
      const cleanedSeeds = [...new Set(seedRefs.map((ref) => String(ref ?? '').trim()).filter(Boolean))];
      if (cleanedSeeds.length > 0) {
        const seededVector = buildVectorPayload(collections[0], truncateEmbeddingForCollection(embedding, collections[0]));
        const seededRes = await fetch(`${process.env.QDRANT_URL ?? 'http://127.0.0.1:6333'}/collections/${collections[0]}/points/query`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            query: Array.isArray(seededVector) ? seededVector : seededVector.vector,
            ...(Array.isArray(seededVector) ? {} : { using: seededVector.name }),
            limit: denseLimit,
            score_threshold: 0.001,
            with_payload: true,
            filter: {
              should: [
                { key: 'source_ref', match: { any: cleanedSeeds } },
                { key: 'sourceRef', match: { any: cleanedSeeds } },
                { key: 'canonicalSourceRef', match: { any: cleanedSeeds } },
                { key: 'file_path', match: { any: cleanedSeeds } },
                { key: 'filePath', match: { any: cleanedSeeds } },
                { key: 'stable_key', match: { any: cleanedSeeds } },
                { key: 'packet_key', match: { any: cleanedSeeds } },
              ],
            },
          }),
          signal: AbortSignal.timeout(5000),
        });

        if (seededRes.ok) {
          const seededData = await seededRes.json();
          const seeded = (seededData as {
            result?: { points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }> };
            points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }>;
          }).result?.points ?? (seededData as {
            points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }>;
          }).points ?? [];

          if (seeded.length > 0) {
            return seeded.map((r) => {
              const payload = (r.payload ?? {}) as Record<string, unknown>;
              return {
                id: String(r.id),
                score: Number(r.score ?? 0),
                text: String(payload.content ?? payload.summary ?? ''),
                metadata: normalizeQdrantMetadata({ ...payload, qdrant_collection: collections[0] }, String(r.id)),
              };
            });
          }
          // Seed filters are only a precision hint. If they are stale or do not
          // match Qdrant payload aliases, fall through to the unfiltered ANN lane
          // instead of masking dense retrieval entirely.
        }
      }
    }

    const collectionResults = await Promise.allSettled(
      collections.map((collection) => searchCodebaseAnn(
        truncateEmbeddingForCollection(embedding, collection),
        denseLimit,
        undefined,
        collection
      ))
    );

    const mergedResults = new Map<string, { id: string; score: number; text?: string; metadata?: Record<string, unknown> }>();
    for (let i = 0; i < collectionResults.length; i++) {
      const collection = collections[i]!;
      const settled = collectionResults[i]!;
      if (settled.status !== 'fulfilled') continue;
      for (const r of settled.value) {
        const id = String(r.qdrant_id ?? r.stable_key ?? r.file_path ?? '');
        if (!id) continue;
        const current = mergedResults.get(id);
        const next = {
          id,
          score: r.semantic_score,
          text: String(r.content ?? ''),
          metadata: normalizeQdrantMetadata(
            {
              ...r,
              packet_key: r.packet_key ?? r.stable_key,
              source_ref: r.source_ref ?? r.file_path,
              content_hash: r.content_hash ?? r.contentHash,
              tree_node_id: r.tree_node_id ?? r.treeNodeId,
              feature_id: r.feature_id ?? r.featureId,
              feature_label: r.feature_label ?? r.featureLabel,
              workspace_revision: r.workspace_revision ?? r.workspaceRevision,
              qdrant_collection: collection,
            },
            String(r.qdrant_id ?? r.stable_key ?? r.file_path ?? '')
          ),
        };
        if (!current || next.score > current.score) mergedResults.set(id, next);
      }
    }

    if (mergedResults.size > 0) {
      return [...mergedResults.values()];
    }

    const topologyHits = await queryTopology64Signal(embedding, denseLimit).catch(() => []);
    if (topologyHits.length > 0) return topologyHits;

    if (!seedRefs.length) return [];

    const cleanedSeeds = [...new Set(seedRefs.map((ref) => String(ref ?? '').trim()).filter(Boolean))];
    if (!cleanedSeeds.length) return [];

    const seededVector = buildVectorPayload('codebase_chunks_768', truncateEmbeddingForCollection(embedding, 'codebase_chunks_768'));
    const res = await fetch(`${process.env.QDRANT_URL ?? 'http://127.0.0.1:6333'}/collections/codebase_chunks_768/points/query`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        query: Array.isArray(seededVector) ? seededVector : seededVector.vector,
        ...(Array.isArray(seededVector) ? {} : { using: seededVector.name }),
        limit: denseLimit,
        score_threshold: 0.001,
        with_payload: true,
        filter: {
          should: [
            { key: 'source_ref', match: { any: cleanedSeeds } },
            { key: 'sourceRef', match: { any: cleanedSeeds } },
            { key: 'canonicalSourceRef', match: { any: cleanedSeeds } },
            { key: 'file_path', match: { any: cleanedSeeds } },
            { key: 'filePath', match: { any: cleanedSeeds } },
            { key: 'stable_key', match: { any: cleanedSeeds } },
            { key: 'packet_key', match: { any: cleanedSeeds } },
          ],
        },
      }),
      signal: AbortSignal.timeout(5000),
    });

    if (!res.ok) return [];
    const data = await res.json();
    const seeded = (data as {
      result?: { points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }> };
      points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }>;
    }).result?.points ?? (data as {
      points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }>;
    }).points ?? [];

    return seeded.map((r) => {
      const payload = (r.payload ?? {}) as Record<string, unknown>;
      return {
        id: String(r.id),
        score: Number(r.score ?? 0),
        text: String(payload.content ?? payload.summary ?? ''),
        metadata: normalizeQdrantMetadata({ ...payload, qdrant_collection: 'codebase_chunks_768' }, String(r.id)),
      };
    });
  } catch (err) {
    console.error('Qdrant search failed:', err);
    return [];
  }
}

async function queryTopology64Signal(
  embedding: number[],
  denseLimit: number
): Promise<Array<{ id: string; score: number; text?: string; metadata?: Record<string, unknown> }>> {
  const { buildVectorPayload } = await import('$lib/server/config/vector-config.js');
  const topologyVector = await Promise.race([
    (async () => {
      const { encode768to64 } = await import('$lib/server/gpu/encode-768-to-64.js');
      return encode768to64(new Float32Array(embedding));
    })(),
    new Promise<null>((resolve) => setTimeout(() => resolve(null), 1500)),
  ]);
  if (!topologyVector) return [];

  const topologyVectorPayload = buildVectorPayload('codebase_topology_64', Array.from(topologyVector));
  const topologyRes = await fetch(`${process.env.QDRANT_URL ?? 'http://127.0.0.1:6333'}/collections/codebase_topology_64/points/query`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      query: Array.isArray(topologyVectorPayload) ? topologyVectorPayload : topologyVectorPayload.vector,
      ...(Array.isArray(topologyVectorPayload) ? {} : { using: topologyVectorPayload.name }),
      limit: denseLimit,
      score_threshold: 0.001,
      with_payload: true,
    }),
    signal: AbortSignal.timeout(5000),
  }).catch(() => null);

  if (!topologyRes?.ok) return [];
  const topologyData = await topologyRes.json();
  const topologyRows = Array.isArray((topologyData as { result?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }> }).result)
    ? ((topologyData as { result: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }> }).result ?? [])
    : Array.isArray((topologyData as { points?: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }> }).points)
      ? ((topologyData as { points: Array<{ id: string | number; score: number; payload?: Record<string, unknown> }> }).points ?? [])
    : [];

  return topologyRows.map((r) => {
    const payload = (r.payload ?? {}) as Record<string, unknown>;
    return {
      id: String(r.id),
      score: Number(r.score ?? 0),
      text: String(payload.content ?? payload.summary ?? ''),
      metadata: normalizeQdrantMetadata({ ...payload, qdrant_collection: 'codebase_topology_64' }, String(r.id)),
    };
  });
}

function deriveGraphConceptSeeds(query: string, extracted: Array<{ name: string; confidence: number }>): string[] {
  const extractedNames = extracted
    .map((concept) => concept.name.trim())
    .filter(Boolean);

  if (extractedNames.length > 0) {
    return [...new Set(extractedNames.map((name) => name.toLowerCase()))].slice(0, RETRIEVAL_LIMITS.maxExactKeywords);
  }

  const rawTerms = query
    .toLowerCase()
    .split(/[^a-z0-9_/-]+/g)
    .map((term) => term.trim())
    .filter((term) => term.length >= 4);

  const stopWords = new Set([
    'find',
    'show',
    'what',
    'when',
    'where',
    'how',
    'does',
    'this',
    'that',
    'with',
    'from',
    'into',
    'next',
    'then',
    'lane',
    'open',
    'done',
  ]);

  return [...new Set(rawTerms.filter((term) => !stopWords.has(term)))].slice(0, RETRIEVAL_LIMITS.maxExactKeywords);
}

async function queryNeo4jFileGraphSignal(seedRefs: string[], topK: number): Promise<Array<{
  id: string;
  score: number;
  text?: string;
  metadata?: Record<string, unknown>;
}>> {
  const { toStableFileKey } = await import('./subgraph-seed-neighborhood.js');
  const { expandNeighbours, fetchAuthorityScores } = await import('$lib/server/search/neo4j-rerank.js');
  const normalizedSeeds = [...new Set(
    seedRefs
      .flatMap((ref) => {
        const raw = String(ref ?? '').trim();
        return raw ? [raw, toStableFileKey(raw)] : [];
      })
      .filter((ref) => ref.length > 0),
  )];

  if (!normalizedSeeds.length) return [];

  const expanded = await Promise.all(
    normalizedSeeds.slice(0, topK).map((seed) => expandNeighbours(seed, 1).catch(() => [])),
  );
  const neighborKeys = [...new Set(expanded.flat().map((key) => String(key ?? '').trim()).filter(Boolean))].filter(
    (key) => !normalizedSeeds.includes(key),
  );

  if (!neighborKeys.length) return [];

  const authority = await fetchAuthorityScores(neighborKeys).catch(() => ({}));

  return neighborKeys
    .map((id) => {
      const pagerank = authority[id]?.pagerank ?? 0;
      return {
        id,
        score: Math.min(1, 0.1 + Math.max(0, pagerank)),
        text: id.replace(/^file:/, ''),
        metadata: {
          graph_seed_mode: 'file_stable_key',
          pagerank,
        },
      };
    })
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id))
    .slice(0, topK);
}

async function loadFallbackGraphSeedRefs(pool: Pool, limit: number): Promise<string[]> {
  try {
    const { rows } = await pool.query<{
      source_ref: string | null;
      rel_path: string | null;
    }>(
      `
        select source_ref, rel_path
        from parent_atlas_documents
        where source_ref is not null
        order by updated_at desc nulls last, id desc
        limit $1
      `,
      [Math.max(1, Math.min(limit, RETRIEVAL_LIMITS.defaultFinalResults))],
    );

    return [...new Set(
      rows.flatMap((row) => [row.source_ref, row.rel_path].map((value) => String(value ?? '').trim())).filter(Boolean),
    )];
  } catch {
    return [];
  }
}


/**
 * Run multi-signal RRF ranking combining BM25, concept overlap, ANN, and Neo4j.
 *
 * Workflow:
 * 1. Generate embedding once for vector lanes
 * 2. Run BM25 on atlas_packets.summary (fast, lexical)
 * 3. Run concept overlap on atlas_packets.concept_ids (fast, exact match)
 * 4. Run Qdrant ANN search (fast, dense vector)
 * 5. Run Neo4j graph queries (fast, precomputed relationships)
 * 6. Call combineViaRRF to merge all signals
 * 7. Filter by minScore and return top-K results
 */
export async function multiLaneRetrievalWithRRF(
  query: string,
  pool: Pool,
  opts: RRFIntegrationOptions = {}
): Promise<RRFIntegrationOutput> {
  const t0 = Date.now();
  const {
    k = 60,
    topK = RETRIEVAL_LIMITS.defaultFinalResults,
    minScore = 0.001,
    deduplicateBy = 'id',
    weights = {},
    dispatcherResult,
  } = opts;

  const finalWeights = { ...RRF_DEFAULT_WEIGHTS, ...weights };
  const {
    bm25SearchIndexed,
    conceptOverlapSearch,
    extractQueryConceptsViaGemma,
    queryNeoJsGraphSignal,
    queryNeoJsGraphSignalByNames,
    turbovecSearch,
    computeTopologClusterMatchSignal,
    computeCommunityAuthoritySignal,
    computeTopologyBlendSignal,
    extractCanonicalPacketFromMetadata,
    buildCommunityAuthorityMap,
    mergeTopologyWeights,
    TOPOLOGY_RRF_WEIGHTS,
    generateDispatcherTopologyHits,
    getDispatcherSignalLaneWeight,
    DISPATCHER_RRF_WEIGHTS,
  } = await loadRrfExecutionDeps();

  try {
    let pgvectorMs = 0;
    let gemma4Ms = 0;
    let pgBm25Ms = 0;
    let conceptOverlapMs = 0;
    let qdrantMs = 0;
    let turbovecMs = 0;
    let neo4jMs = 0;
    let dispatcherSignalMs = 0; // Session 117

    // Generate embedding once for all vector lanes
    const tEmbedStart = performance.now();
    const { generateSingleEmbedding } = await import('$lib/server/grpc/embedding-client.js');
    const embedding = await generateSingleEmbedding(query).catch(() => null);
    pgvectorMs = performance.now() - tEmbedStart;

    // Extract concepts from query via Gemma4
    const tGemmaStart = performance.now();
    const conceptExtractionResult = await extractQueryConceptsViaGemma({
      query,
      maxConcepts: 5,
      minConfidence: 0.7,
    }).catch(() => ({ conceptIds: [], extracted: [], durationMs: 0 }));
    gemma4Ms = performance.now() - tGemmaStart;

    const graphConceptSeeds = deriveGraphConceptSeeds(query, conceptExtractionResult.extracted);

    // Run lexical + concept signals first so dense lanes can seed from them
    const bm25Promise = (async () => {
      const start = performance.now();
      const res = await bm25SearchIndexed(query, topK);
      pgBm25Ms = performance.now() - start;
      return res;
    })();

    const conceptPromise = (async () => {
      const start = performance.now();
      const res = await conceptOverlapSearch(conceptExtractionResult.conceptIds, topK);
      conceptOverlapMs = performance.now() - start;
      return res;
    })();

    const [bm25Results, conceptResults] = await Promise.allSettled([
      bm25Promise,
      conceptPromise,
    ]);

    const seedRefs =
      bm25Results.status === 'fulfilled'
        ? bm25Results.value.flatMap((hit) => [hit.file_path, hit.stable_key])
        : [];
    const fallbackSeedRefs = seedRefs.length > 0 ? [] : await loadFallbackGraphSeedRefs(pool, topK);
    const graphSeedRefs = seedRefs.length > 0 ? seedRefs : fallbackSeedRefs;
    const qdrantSeedRefs = graphSeedRefs;

    // Run dense/graph signals in parallel
    const qdrantPromise = (async () => {
      const start = performance.now();
      const res = await queryQdrantVectorSignal(query, embedding, topK, qdrantSeedRefs);
      qdrantMs = performance.now() - start;
      return res;
    })();

    const turbovecPromise = (async () => {
      const start = performance.now();
      const res = embedding ? await turbovecSearch(embedding, { topK: topK * 2, timeoutMs: 300 }) : { candidates: [], backend: 'offline', durationMs: 0 };
      turbovecMs = performance.now() - start;
      return res;
    })();

    const neoPromise = (async () => {
      const start = performance.now();
      const res = await Promise.allSettled([
        conceptExtractionResult.conceptIds.length > 0
          ? queryNeoJsGraphSignal({ conceptIds: conceptExtractionResult.conceptIds, topK }).then((r) =>
              r.map((hit) => ({
                id: hit.id,
                score: hit.score,
                text: hit.text,
                metadata: { graph_seed_mode: 'concept_id' },
              }))
            )
          : Promise.resolve([]),
        graphConceptSeeds.length > 0
          ? queryNeoJsGraphSignalByNames(graphConceptSeeds, topK).then((r) =>
              r.map((hit) => ({
                id: hit.id,
                score: hit.score,
                text: hit.text,
                metadata: { graph_seed_mode: 'concept_name' },
              }))
            )
          : Promise.resolve([]),
        graphSeedRefs.length > 0
          ? queryNeo4jFileGraphSignal(graphSeedRefs, topK).then((r) =>
              r.map((hit) => ({
                id: hit.id,
                score: hit.score,
                text: hit.text,
                metadata: { ...(hit.metadata ?? {}), graph_seed_mode: 'file_stable_key' },
              }))
            )
          : Promise.resolve([]),
      ]).then((results) =>
        results.flatMap((settled) => (settled.status === 'fulfilled' ? settled.value : []))
      );
      neo4jMs = performance.now() - start;
      return res;
    })();

    const [qdrantResults, turbovecResults, neoResults] = await Promise.allSettled([
      qdrantPromise,
      turbovecPromise,
      neoPromise,
    ]);

    // Build community authority map from Neo4j PageRank data for topology signals
    let communityAuthorityMap: Map<number, number> | null = null;
    try {
      const pageRankData = await fetchAuthorityScores(
        neoResults.status === 'fulfilled'
          ? neoResults.value.slice(0, 100).map((r) => r.id)
          : []
      ).catch(() => ({}));

      const pageRankArray = Object.entries(pageRankData).map(([packet_id, data]) => ({
        packet_id,
        community_id: (data as { community_id?: number })?.community_id ?? 0,
        pagerank: (data as { pagerank?: number })?.pagerank ?? 0,
      }));

      if (pageRankArray.length > 0) {
        communityAuthorityMap = buildCommunityAuthorityMap(pageRankArray, 'max');
      }
    } catch (err) {
      console.warn('[RRF] Community authority map build failed:', err);
    }

    // Extract candidate query packet for topology signal computation
    let queryPacket: Partial<Record<string, unknown>> | null = null;
    if (bm25Results.status === 'fulfilled' && bm25Results.value.length > 0) {
      const firstBm25 = bm25Results.value[0];
      queryPacket = extractCanonicalPacketFromMetadata({
        packet_key: firstBm25?.stable_key,
        source_ref: firstBm25?.file_path,
        content_hash: firstBm25?.content_hash ?? firstBm25?.contentHash,
        tree_node_id: firstBm25?.tree_node_id ?? firstBm25?.treeNodeId,
        feature_id: firstBm25?.feature_id ?? firstBm25?.featureId,
        feature_label: firstBm25?.feature_label ?? firstBm25?.featureLabel,
        workspace_revision: firstBm25?.workspace_revision ?? firstBm25?.workspaceRevision,
        som_cluster: firstBm25?.som_cluster,
      });
    }

    // Convert results to ContextHit[] format for RRF
    const bm25Hits: ContextHit[] =
      bm25Results.status === 'fulfilled'
        ? bm25Results.value.map((hit) => ({
            id: hit.id,
            source: 'postgres_trigram' as const,
            score: hit.similarity,
            text: hit.summary,
            metadata: {
              stable_key: hit.stable_key,
              file_path: hit.file_path,
              source_ref: hit.file_path,
              packet_key: hit.stable_key,
              content_hash: hit.content_hash ?? hit.contentHash ?? null,
              tree_node_id: hit.tree_node_id ?? hit.treeNodeId ?? null,
              feature_id: hit.feature_id ?? hit.featureId ?? null,
              feature_label: hit.feature_label ?? hit.featureLabel ?? null,
              workspace_revision: hit.workspace_revision ?? hit.workspaceRevision ?? null,
            },
          }))
        : [];

    const conceptHits: ContextHit[] =
      conceptResults.status === 'fulfilled'
        ? conceptResults.value.map((hit) => ({
            id: hit.id,
            source: 'concept_overlap' as const,
            score: hit.overlapScore,
          }))
        : [];

    // Defense-in-depth: even though the collection query itself is now 768-only (see the
    // codebase_chunks_384_hybrid crash-bug fix above), still gate each hit's own metadata
    // through resolveEmbeddingLane() before it enters RRF — a lane resolver that exists in the
    // repo but was previously wired into nothing (only its own spec test referenced it). Only
    // drops hits explicitly identified as legacy-384 (LEGACY_DIMENSION_EXPLICIT_ONLY); does NOT
    // drop hits with an UNKNOWN resolution, since this repo's collection/vector-name registries
    // are not guaranteed exhaustive and an over-eager filter here would silently reduce recall.
    const qdrantHits: ContextHit[] =
      qdrantResults.status === 'fulfilled'
        ? qdrantResults.value
            .filter((hit) => {
              const m = hit.metadata ?? {};
              const resolution = resolveEmbeddingLane({
                collection: (m.qdrant_collection as string | undefined) ?? undefined,
                embedding_dim: Array.isArray((m as any).vector) ? (m as any).vector.length : undefined,
              });
              if (resolution.reason === EmbeddingLaneTelemetryReason.LEGACY_DIMENSION_EXPLICIT_ONLY) {
                emitEmbeddingLaneTelementry(String((m as any).packet_key ?? hit.id), resolution);
                return false;
              }
              return true;
            })
            .map((hit) => ({
              id: hit.id,
              source: 'qdrant_vector' as const,
              score: hit.score,
              text: hit.text,
              metadata: hit.metadata,
            }))
        : [];

    const turbovecHits: ContextHit[] =
      turbovecResults.status === 'fulfilled'
        ? turbovecResults.value.candidates.map((hit) => {
            const identity = hit.identity ?? {};
            return {
              id: hit.id,
              source: 'turbovec_ann' as const,
              score: hit.score,
              text: hit.id,
              metadata: {
                turbovec_candidate_id: hit.id,
                turbovec_cluster: hit.cluster,
                packet_key: identity.packetKey ?? null,
                source_ref: identity.sourceRef ?? null,
                content_hash: identity.contentHash ?? null,
                symbol_version_id: identity.symbolVersionId ?? null,
                source_revision: identity.sourceRevision ?? null,
                workspace_revision: identity.workspaceRevision ?? null,
                namespace: identity.namespace ?? null,
                turbovec_identity_provenance: identity,
              },
            };
          })
        : [];

    const neoHits: ContextHit[] =
      neoResults.status === 'fulfilled'
        ? neoResults.value.map((hit) => ({
            id: hit.id,
            source: 'neo4j_graph' as const,
            score: hit.score,
            text: hit.text,
            metadata: { neo4j_paths: hit.paths ?? 0 },
          }))
        : [];

    // Topology signals: SOM cluster match and community authority
    // These are computed for each candidate from qdrant results (which contain topolog_cluster and community_id)
    const topologyClusterHits: ContextHit[] =
      qdrantResults.status === 'fulfilled'
        ? qdrantResults.value
            .map((hit) => {
              const candidatePacket = extractCanonicalPacketFromMetadata(hit.metadata ?? {});
              const clusterScore = computeTopologClusterMatchSignal(
                candidatePacket as Parameters<typeof computeTopologClusterMatchSignal>[0],
                queryPacket as unknown as Parameters<typeof computeTopologClusterMatchSignal>[1],
                0.5
              );

              return {
                id: hit.id,
                source: 'som_topology' as const,
                score: clusterScore,
                text: hit.text,
                metadata: {
                  topolog_cluster: candidatePacket.topolog_cluster,
                  som_cluster: candidatePacket.som_cluster,
                  query_cluster: queryPacket?.topolog_cluster,
                },
              };
            })
            .filter((hit) => hit.score > 0.5) // Only include cluster hits with meaningful scores
        : [];

    const communityAuthorityHits: ContextHit[] =
      qdrantResults.status === 'fulfilled' && communityAuthorityMap
        ? qdrantResults.value
            .map((hit) => {
              const candidatePacket = extractCanonicalPacketFromMetadata(hit.metadata ?? {});
              const authorityScore = computeCommunityAuthoritySignal(
                candidatePacket as Parameters<typeof computeCommunityAuthoritySignal>[0],
                communityAuthorityMap,
                0.5
              );

              return {
                id: hit.id,
                source: 'neo4j_community' as const,
                score: authorityScore,
                text: hit.text,
                metadata: {
                  community_id: candidatePacket.community_id,
                  authority_score: authorityScore,
                },
              };
            })
            .filter((hit) => hit.score > 0.5) // Only include authority hits with meaningful scores
        : [];

    // Session 117: Extract dispatcher topology signals
    let dispatcherSignalHits: ContextHit[] = [];
    if (dispatcherResult) {
      const tDispatcherStart = performance.now();
      try {
        // Generate dispatcher signal hits using all qdrant results as candidate pool
        const candidateCount = qdrantResults.status === 'fulfilled' ? qdrantResults.value.length : 0;
        if (candidateCount > 0) {
          dispatcherSignalHits = generateDispatcherTopologyHits({
            dispatcherResult,
            candidateCount,
            queryPacketKey: bm25Results.status === 'fulfilled' ? bm25Results.value[0]?.stable_key : undefined,
          });
        }
      } catch (err) {
        console.warn('[RRF] Dispatcher signal extraction failed:', err);
      }
      dispatcherSignalMs = performance.now() - tDispatcherStart;
    }

    const tRerankStart = performance.now();
    // Combine via RRF with topology signals (including dispatcher signals from Session 117)
    // Every lane is normalized to its canonical dedup identity first (symbol_version_id ->
    // packet_key -> source_ref -> lane id) so combineViaRRF's deduplicateBy:'id' collapses
    // on the same symbol across lanes/projections instead of on lane-local point/stable keys.
    const lanes = [
      bm25Hits,
      conceptHits,
      qdrantHits,
      turbovecHits,
      neoHits,
      topologyClusterHits,     // SOM topology signal lane
      communityAuthorityHits,  // Community authority signal lane
      dispatcherSignalHits,    // Session 117: Dispatcher topology signal lane
    ].map(normalizeCanonicalIdentity);
    const laneNames: RetrievalLaneName[] = [
      'postgres_trigram',
      'concept_overlap',
      'qdrant_vector',
      'turbovec_ann',
      'neo4j_graph',
      'som_topology',
      'neo4j_community',
      'dispatcher_signal',     // Session 117
    ];

    const rrfResults = combineViaRRF(lanes, laneNames, {
      k,
      weights: finalWeights,
      deduplicateBy,
    });

    // Filter and slice
    const filtered = rrfResults.filter((r) => r.combinedScore >= minScore).slice(0, topK);
    const rerankMs = performance.now() - tRerankStart;

    return {
      results: filtered,
      breakdown: {
        bm25Count: bm25Hits.length,
        conceptCount: conceptHits.length,
        qdrantCount: qdrantHits.length,
        turbovecCount: turbovecHits.length,
        neoCount: neoHits.length,
        topologyClusterCount: topologyClusterHits.length,
        communityAuthorityCount: communityAuthorityHits.length,
        dispatcherSignalCount: dispatcherSignalHits.length, // Session 117
      },
      durationMs: Date.now() - t0,
      timings: {
        bm25_ms: pgBm25Ms,
        qdrant_ms: qdrantMs,
        turbovec_ms: turbovecMs,
        neo4j_ms: neo4jMs,
        redis_ms: 0,
        gemma4_ms: gemma4Ms,
        rrf_ms: rerankMs,
        pgvector_ms: pgvectorMs,
        concept_overlap_ms: conceptOverlapMs,
        topology_ms: topologyClusterHits.length > 0 ? rerankMs * 0.1 : 0,
        dispatcher_signal_ms: dispatcherSignalMs, // Session 117
      },
    };
  } catch (error) {
    console.error('RRF integration error:', error);
    return {
      results: [],
      breakdown: {
        bm25Count: 0,
        conceptCount: 0,
        qdrantCount: 0,
        turbovecCount: 0,
        neoCount: 0,
        topologyClusterCount: 0,
        communityAuthorityCount: 0,
        dispatcherSignalCount: 0,
      },
      durationMs: Date.now() - t0,
      timings: {
        bm25_ms: 0,
        qdrant_ms: 0,
        turbovec_ms: 0,
        neo4j_ms: 0,
        redis_ms: 0,
        gemma4_ms: 0,
        rrf_ms: 0,
        pgvector_ms: 0,
        concept_overlap_ms: 0,
        topology_ms: 0,
        dispatcher_signal_ms: 0,
      },
    };
  }
}

/**
 * Compute information retrieval metrics for RRF evaluation.
 *
 * DCG@K: Σ_{i=1}^{K} (rel_i / log2(i+1)) where rel_i ∈ [0,1]
 * NDCG@K: DCG@K / ideal_DCG@K
 * MRR@K: 1 / rank of first relevant result
 */
export function computeMetrics(
  results: RRFResult[],
  relevanceLabels: Record<string, number>, // id → relevance [0,1]
  k: number = 10
): {
  dcg: number;
  ndcg: number;
  mrr: number;
  recall: number;
} {
  const topK = results.slice(0, k);
  let dcg = 0;
  let mrrFound = false;
  let mrrValue = 0;
  let relevantCount = 0;

  for (let i = 0; i < topK.length; i++) {
    const relevance = relevanceLabels[topK[i].id] ?? 0;
    dcg += relevance / Math.log2(i + 2);

    if (!mrrFound && relevance > 0) {
      mrrValue = 1 / (i + 1);
      mrrFound = true;
    }

    if (relevance > 0) relevantCount++;
  }

  const totalRelevant = Object.values(relevanceLabels).filter((rel) => rel > 0).length;
  const recall = totalRelevant > 0 ? relevantCount / totalRelevant : 0;

  // Ideal DCG: sort labels descending, compute DCG
  const sortedRelevance = Object.values(relevanceLabels)
    .sort((a, b) => b - a)
    .slice(0, k);

  let idealDcg = 0;
  for (let i = 0; i < sortedRelevance.length; i++) {
    idealDcg += sortedRelevance[i] / Math.log2(i + 2);
  }

  const ndcg = idealDcg > 0 ? dcg / idealDcg : 0;

  return {
    dcg: Math.round(dcg * 1000) / 1000,
    ndcg: Math.round(ndcg * 1000) / 1000,
    mrr: mrrFound ? Math.round(mrrValue * 1000) / 1000 : 0,
    recall: Math.round(recall * 1000) / 1000,
  };
}

rrfCombiner.text:
/**
 * Reciprocal Rank Fusion (RRF) Combiner
 *
 * Combines multiple ranked lists via: RRF(d) = Σ weight_i / (k + rank_i(d))
 * Typically beats vector-only retrieval by 15-30%.
 */

export type RetrievalLaneName =
  | 'postgres_trigram'
  | 'qdrant_vector'
  | 'turbovec_ann'
  | 'concept_overlap'
  | 'neo4j_graph'
  | 'redis_cache'
  | 'ast_symbol'
  | 'som_topology'
  | 'neo4j_community'
  | 'web_research'
  | 'dispatcher_signal'; // Session 117: Dispatcher topology signals

export interface ContextHit {
  id: string;
  source: RetrievalLaneName;
  score: number;
  text?: string;
  metadata?: Record<string, unknown>;
}

export interface RRFOptions {
  k?: number;
  weights?: Record<string, number>;
  deduplicateBy?: 'id' | 'text';
}

export interface RRFScore {
  hitId: string;
  laneName: RetrievalLaneName;
  laneRank: number;
  laneScore: number;
  rrfComponent: number;
  metadata?: Record<string, unknown>;
}

export interface RRFResult {
  id: string;
  combinedScore: number;
  source: RetrievalLaneName;
  sources: RetrievalLaneName[];
  text?: string;
  metadata?: Record<string, unknown>;
  breakdown: RRFScore[];
}

/**
 * Merge every lane's metadata for a single deduplicated hit, key by key, keeping the first
 * non-null/non-undefined value seen for each key across lanes (in their original order).
 * Unlike picking one lane's whole object, this can't let an earlier lane's all-null identity
 * fields shadow a later lane's real values for the same key.
 */
function mergeLaneMetadata(scores: RRFScore[]): Record<string, unknown> | undefined {
  let merged: Record<string, unknown> | undefined;
  for (const score of scores) {
    if (!score.metadata) continue;
    for (const [key, value] of Object.entries(score.metadata)) {
      if (!merged) merged = {};
      const existing = merged[key];
      if (existing === undefined || existing === null) {
        merged[key] = value;
      }
    }
  }
  return merged;
}

/**
 * Combine multiple ranked lists via Reciprocal Rank Fusion (RRF).
 *
 * Formula: RRF(d) = Σ_i (weight_i / (k + rank_i(d)))
 *
 * Example:
 *   BM25 rank = 3, weight = 1   → 1/(60+3) = 0.0159
 *   ANN rank = 12, weight = 1   → 1/(60+12) = 0.0137
 *   Concept rank = 5, weight = 1 → 1/(60+5) = 0.0152
 *   ────────────────────────────
 *   RRF score = 0.0448
 */
export function combineViaRRF(
  lanes: ContextHit[][],
  laneNames: RetrievalLaneName[],
  options: RRFOptions = {}
): RRFResult[] {
  const { k = 60, weights = {}, deduplicateBy = 'id' } = options;

  // Map: hitKey → laneName → best score from that lane.
  // A lane may surface the same canonical id multiple times (e.g. two Qdrant
  // projections of the same packet). Those repeated projections must not
  // cast multiple independent votes for the same candidate.
  const hitScores = new Map<string, Map<RetrievalLaneName, RRFScore>>();

  // Populate scores from each lane
  lanes.forEach((hits, laneIndex) => {
    const laneName = laneNames[laneIndex];
    const laneWeight = weights[laneName] ?? 1.0;

    hits.forEach((hit, rank) => {
      const hitKey = deduplicateBy === 'text' ? hit.text || hit.id : hit.id;
      const rrfComponent = laneWeight / (k + (rank + 1)); // 1-indexed

      if (!hitScores.has(hitKey)) {
        hitScores.set(hitKey, new Map());
      }

      const perLane = hitScores.get(hitKey)!;
      const existing = perLane.get(laneName);
      const candidateScore: RRFScore = {
        hitId: hit.id,
        laneName,
        laneRank: rank + 1,
        laneScore: hit.score,
        rrfComponent,
        metadata: hit.metadata,
      };
      if (!existing || candidateScore.rrfComponent > existing.rrfComponent) {
        perLane.set(laneName, candidateScore);
      }
    });
  });

  // Combine scores and sort
  const results: RRFResult[] = [];
  for (const [hitKey, perLane] of hitScores) {
    const scores = [...perLane.values()];
    const combinedScore = scores.reduce((sum, s) => sum + s.rrfComponent, 0);
    const primaryHit = scores[0]; // Use identity (id/source) from first lane
    // Field-level metadata merge across every lane that reported this hit — NOT "first lane
    // with a non-empty object". A lane's metadata object can carry a full identity-field shape
    // (packet_key/source_ref/content_hash/tree_node_id/workspace_revision) with every value
    // null (common for lexical-only lanes never joined to a chunk record). Picking by object
    // presence alone let an earlier, all-null lane's object silently outrank a later lane's
    // real values for the same field — e.g. a postgres_trigram null tree_node_id beating a
    // qdrant_vector hit's real tree_node_id for the same deduplicated id. Merge key-by-key
    // instead, keeping the first non-null/non-undefined value seen for each key across lanes
    // in their original order.
    const metadata = mergeLaneMetadata(scores) ?? primaryHit.metadata;

    results.push({
      id: primaryHit.hitId,
      combinedScore,
      source: primaryHit.laneName,
      sources: [...new Set(scores.map((s) => s.laneName))],
      text: hitKey,
      metadata,
      breakdown: scores,
    });
  }

  // Sort by combined score descending
  return results.sort((a, b) => b.combinedScore - a.combinedScore);
}

